class Gizmo {
    // No 'extends' specified, so compiler inserts: extends java.lang.Object
}

public class ObjectAncestryDemo {
    public static void main(String[] args) {
        Gizmo g = new Gizmo();

        // 1. Inherited getClass()
        System.out.println("Runtime Class: " + g.getClass().getName());

        // 2. Superclass of Gizmo
        System.out.println("Superclass: " + g.getClass().getSuperclass().getName());

        // 3. Superclass of Object is null (end of line!)
        System.out.println("Superclass of Object: " + Object.class.getSuperclass());

        // 4. Object as universal container
        Object[] diverseArray = new Object[] {"Text", 100, g};
        System.out.println("Array elements stored: " + diverseArray.length);
    }
}

