class Sensor {
    private int sensorId;
    public Sensor(int id) { this.sensorId = id; }
}

public class DefaultObjectDemo {
    public static void main(String[] args) {
        Sensor s1 = new Sensor(42);

        // Default Object.toString() output: ClassName@HexHashCode
        String defaultStr = s1.toString();
        System.out.println("Default toString: " + defaultStr);

        // Hash code in hex matches the tail of default toString
        String hexHash = Integer.toHexString(s1.hashCode());
        System.out.println("Hex HashCode:    " + hexHash);

        boolean matches = defaultStr.endsWith(hexHash);
        System.out.println("String ends with hex hash: " + matches);
    }
}

