class Alpha {}
class Beta extends Alpha {}
class Gamma extends Beta {}

class HierarchyWalker {
    public static void printAncestry(Class<?> clazz) {
        Class<?> current = clazz;
        while (current != null) {
            System.out.println(" -> " + current.getName());
            current = current.getSuperclass();
        }
    }
}

public class AncestryApp {
    public static void main(String[] args) {
        HierarchyWalker.printAncestry(Gamma.class);
    }
}

import java.util.HashMap;
import java.util.Map;

class AnyCache {
    private Map<String, Object> storage = new HashMap<>();

    public void put(String key, Object value) {
        storage.put(key, value);
    }

    public Object get(String key) {
        return storage.get(key);
    }

    public <T> T getAs(String key, Class<T> expectedType) {
        Object obj = storage.get(key);
        if (obj == null) return null;
        return expectedType.cast(obj);
    }
}

public class CacheApp {
    public static void main(String[] args) {
        AnyCache cache = new AnyCache();
        cache.put("max_connections", 50);
        cache.put("server_name", "Prod-Cluster-01");

        Integer conns = cache.getAs("max_connections", Integer.class);
        String name = cache.getAs("server_name", String.class);

        System.out.println("[Cache] max_connections = " + conns);
        System.out.println("[Cache] server_name = " + name);
    }
}

