import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

interface EventListener {
    void onEvent(String topic, Object payload);
}

class SimpleEventBus {
    private Map<String, List<EventListener>> listeners = new HashMap<>();

    public void subscribe(String topic, EventListener listener) {
        listeners.computeIfAbsent(topic, k -> new ArrayList<>()).add(listener);
    }

    public void publish(String topic, Object payload) {
        List<EventListener> list = listeners.get(topic);
        if (list != null) {
            for (EventListener l : list) {
                l.onEvent(topic, payload);
            }
        }
    }
}

public class EventBusApp {
    public static void main(String[] args) {
        SimpleEventBus bus = new SimpleEventBus();

        EventListener handler = (topic, payload) -> {
            if (payload instanceof String) {
                System.out.println("[Text Event on " + topic + "] " + payload);
            } else if (payload instanceof Integer) {
                System.out.println("[Numeric Metric on " + topic + "] Value: " + payload);
            }
        };

        bus.subscribe("system.alert", handler);
        bus.subscribe("system.metric", handler);

        bus.publish("system.alert", "CPU Temperature High");
        bus.publish("system.metric", 95);
    }
}
